#include "stdafx.h"#include "TrendsRsuKernel.h"#include <rsuPaths.h>#include <rsuErr.h>#include <TrendsDefines.h>HANDLE HandleT(bool bHeader){  char szFile[_MAX_PATH];  sprintf_s( szFile, "%s_Trends.dat", rsuGetTrendPath() );  if( bHeader )    strcat_s( szFile, ".hdr" );  //  HANDLE hHandle = ::CreateFile( szFile,                                  GENERIC_READ|GENERIC_WRITE,                                  FILE_SHARE_READ|FILE_SHARE_WRITE,//|FILE_SHARE_DELETE,                                  NULL,                                  OPEN_ALWAYS,                                  FILE_ATTRIBUTE_ARCHIVE,                                  NULL );  return hHandle;}//bool KTrendsRsuKernel::OpenTrendHead(){  if ( m_pHeadT   ) return true;  //  HANDLE hVarFile = HandleT(true);  if ( hVarFile != INVALID_HANDLE_VALUE )  {    DWORD dwSize = 1024*32*sizeof(STrendId);// 32000 имен    if ( Count() )      dwSize = Count()*sizeof(STrendId)+sizeof(CTrendHeader);    //    m_hMapHead = ::CreateFileMapping( hVarFile, NULL, PAGE_READWRITE ,0, dwSize, FormatMappingHeaderTrends );    if ( m_hMapHead != NULL )    {      ::CloseHandle ( hVarFile );      m_pHeadT = (CTrendHeaderEx*)MapView( m_hMapHead, 0, dwSize );      ASS( m_pHeadT );      if( !m_pHeadT )        return false;      m_pHeadT->nVersion = 0;      m_pHeadT->dwName   = 0;      m_pHeadT->kBlk     = 0;      m_pHeadT->kVar     = 0;      m_nInterval = max(1,m_nInterval);      if ( m_nInterval < 1 )        m_pHeadT->StepTc = 1;      else        m_pHeadT->StepTc = m_nInterval;      //      return true;    }  }  DWORD Err = GetLastError();  ASS(FALSE);  return false;}//bool KTrendsRsuKernel::OpenTrendData(DWORD dwName){  if ( m_hMapData )     ::CloseHandle( m_hMapData );  //  unsigned __int64 size = GetTrendSize();  DWORD dwLow  = DWORD(size);  DWORD dwHigh = DWORD(size>>32);  HANDLE hVarFile = HandleT(false);  if ( hVarFile != INVALID_HANDLE_VALUE )  {    char szName[32];    sprintf_s( szName, FormatMappingDataTrends, dwName);    //    m_hMapData = ::CreateFileMapping( hVarFile, NULL, PAGE_READWRITE , dwHigh, dwLow, szName );    if ( m_hMapData != NULL )    {      ::CloseHandle ( hVarFile );      return true;    }  }  //  // ::MessageBox( NULL, "Нет места на диске.\n"  //                     "Удалите лишнюю информацию на ж¸стком диске.\n"  //                     "И перезапустите модель.", "Ошибка", MB_ICONSTOP|MB_SYSTEMMODAL );  DWORD Err = ::GetLastError();  // LogMsg( "Ошибка OpenTrendData(DWORD dwName) '%d' '%d' low %lX high %lX", Err, dwName, dwLow, dwHigh );  // ASS(FALSE);  return false;}//// Запись в файл трендовvoid KTrendsRsuKernel::WriteTrends(){  if( !m_dwBlkAlloc )    m_dwBlkAlloc = maxBlocksOut;  if( m_pDataT == NULL )  {    UnmapViewOfFile( pbBegWnd );    DWORD dwBklTotal = m_dwBklTotal;    m_dwBklTotal = (m_dwBklTotal/m_dwBlkAlloc)*m_dwBlkAlloc;    MapTrends();    m_dwBklTotal = dwBklTotal;  }  else if ( (m_dwBklTotal % m_dwBlkAlloc) == 0 )  {    // Смена окна    UnmapViewOfFile( pbBegWnd );    MapTrends();  }  else if( m_AllocLeft < m_nSizeVar )  {    ASSD(0);    // Смена окна    UnmapViewOfFile( pbBegWnd );    MapTrends();  }  //  float * pTrend = m_pDataT;  if( !m_pDataT || IsBadWritePtr( m_pDataT, m_nSizeVar) )    return;  //  UINT nCount = Count();  STrendDef* list = (STrendDef*)Obj(0);  for ( UINT n = 0; n < nCount; n++ )  {    float v = 0;    switch ( list[n].eVal )    {    case enumValueDbl: v = (float)(*(double*)list[n].Void);break;    case enumValueInt: v = (float)(*(int   *)list[n].Void);break;    case enumValueChr: v = (float)(*(char  *)list[n].Void);break;    case enumValueBol:       if( -1!=list[n].bitOffset )        v = (*(int*)list[n].Void)&(1<<list[n].bitOffset) ? 1.f : 0;      else        v = (float)(*(bool  *)list[n].Void);      break;    case enumValueFlt: v = (float)(*(float *)list[n].Void);break;    case enumValueI2:  v = (float)(*(short *)list[n].Void);break;    case enumValueUI2: v = (float)(*(WORD  *)list[n].Void);break;    case enumValueUI4: v = (float)(*(DWORD  *)list[n].Void);break;    }    *pTrend++ = v;  }  //  m_dwBklTotal++;  m_pHeadT->kBlk++;  m_pDataT += nCount;  m_AllocLeft -= m_nSizeVar;}//UINT64 KTrendsRsuKernel::GetTrendSize(){  UINT64 r = m_nSizeMB;  r *= 1024;  r *= 1024;  SYSTEM_INFO SI;  GetSystemInfo( &SI );  DWORD dwAllocKvant = SI.dwAllocationGranularity;  r /= dwAllocKvant;  r *= dwAllocKvant;  return r;}// Смена окнаvoid KTrendsRsuKernel::MapTrends(){  float* curDataT = m_pDataT;  m_pDataT = NULL;  pbBegWnd = NULL;  //  SYSTEM_INFO SI;  GetSystemInfo( &SI );  //  UINT64 StartAddr  = m_dwBklTotal * m_nSizeVar;  UINT64 kPage      = StartAddr / SI.dwAllocationGranularity;  UINT64 StartWnd   = kPage * SI.dwAllocationGranularity;   UINT64 AllocSize  = m_nSizeVar * m_dwBlkAlloc;  UINT64 AllocPages = AllocSize / SI.dwAllocationGranularity + 2;  AllocSize = AllocPages * SI.dwAllocationGranularity;  //  // Увеличение файла трендов  if ( m_nAddMB > 0 )  {    if ( (StartWnd + AllocSize) >= GetTrendSize() )    {      while ( (StartWnd + AllocSize) >= GetTrendSize() )        m_nSizeMB += m_nAddMB;      //      //CSemLock LockIniTrends ( "Trends access", 5000 );      m_pHeadT->dwName++;      OpenTrendData(m_pHeadT->dwName);    }  }  if( !m_dwBlkAlloc )    m_dwBlkAlloc = maxBlocksOut;  while( pbBegWnd == NULL )  {    DWORD err = GetLastError();    AllocSize  = m_nSizeVar * m_dwBlkAlloc;    AllocPages = AllocSize  / SI.dwAllocationGranularity + 2;    AllocSize  = AllocPages * SI.dwAllocationGranularity;    pbBegWnd = MapView( m_hMapData, StartWnd, AllocSize );    m_AllocLeft = AllocSize;    if( pbBegWnd )      break;    m_dwBlkAlloc /= 2;    if ( m_dwBlkAlloc == 0 )       return;// Это уже большая жопа  }  if( NULL==pbBegWnd )    return;  m_pDataT = (float*)(pbBegWnd + ( StartAddr - StartWnd ));  if ( pbBegWnd == NULL )  {    DWORD Err = GetLastError();    //LogMsg( "Ошибка MapTrends() '%d'", Err );    ASS(FALSE);  }}BYTE* KTrendsRsuKernel::MapView( HANDLE hHandle, UINT64 dwOffset, SIZE_T dwSize ){  DWORD dwLow  = dwOffset;  DWORD dwHigh = dwOffset>>32;  return (BYTE*)::MapViewOfFile( hHandle, FILE_MAP_ALL_ACCESS, dwHigh, dwLow, dwSize );}